package com.smarthub.plus;
import android.app.*;import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;import java.lang.reflect.*;import java.util.*;import java.util.concurrent.*;

/** Device acceptance uses the user's supplied export from app cache, never a bundled channel fixture. */
final class LauncherAcceptance32 {
 private static Object field(Object object,Class<?> type,String name)throws Exception{Field f=type.getDeclaredField(name);f.setAccessible(true);return f.get(object);}
 private static Rect rect(NowNextView root,View view){Rect r=new Rect();view.getDrawingRect(r);root.offsetDescendantRectToMyCoords(view,r);return r;}
 private static void require(boolean condition,String message){if(!condition)throw new AssertionError(message);}
 static void run(Instrumentation test,Context c,Bundle out)throws Exception{
  File input=new File(c.getCacheDir(),"import32.chl");if(input.isFile())try(Reader reader=new InputStreamReader(new FileInputStream(input),java.nio.charset.StandardCharsets.UTF_8)){ChlLogoAddon.get(c).importFile(reader);}finally{input.delete();}
  ReceiverCatalog db=ReceiverCatalog.get(c);db.ensure();out.putInt("catalog_channels",db.count());out.putInt("catalog_satellites",db.satellites().size());require(db.count()==10644,"Actual CHL catalogue missing");
  long start=System.nanoTime();List<ReceiverCatalog.Channel> mbc=db.channels("MBC2",-1,-1,false,true);out.putLong("mbc2_sql_ms",(System.nanoTime()-start)/1000000);out.putInt("mbc2_results",mbc.size());require(!mbc.isEmpty(),"MBC alias SQL search failed");require(out.getLong("mbc2_sql_ms")<2000,"SQL search exceeded latency budget");
  List<ReceiverCatalog.Channel> rf=db.channels("12419H",-1,-1,false,false);require(!rf.isEmpty(),"RF search failed");boolean radio=false;for(ReceiverCatalog.Channel ch:db.channels("",-1,1,false,false))radio|=ch.tv==1;out.putBoolean("radio_metadata",radio);require(radio,"Full CHL type metadata was lost");
  ReceiverCatalog.Channel first=rf.get(0);boolean old=db.favorite(first.id);db.favorite(first.id,true);boolean selected=false;for(ReceiverCatalog.Channel ch:db.channels("",-1,-1,true,false))selected|=ch.id==first.id;db.favorite(first.id,old);out.putBoolean("favorites_roundtrip",selected);require(selected,"Favourite did not persist");
  int count=db.count();boolean rejected=false;try{db.importText("{\"Type\":\"sat\",\"Index\":0,\"Name\":\"Invalid incomplete export\",\"Angle\":0,\"Band\":\"KU\"}");}catch(Exception expected){rejected=true;}out.putBoolean("bad_import_rolls_back",rejected&&db.count()==count);require(out.getBoolean("bad_import_rolls_back"),"Import rollback failed");
  Activity library=test.startActivitySync(new Intent(c,ReceiverChannelsActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));test.runOnMainSync(()->{try{((EditText)field(library,ReceiverLibraryActivity.class,"query")).setText("MBC2");}catch(Exception e){throw new RuntimeException(e);}});int[] shown={0};for(int n=0;n<60;n++){Thread.sleep(150);test.runOnMainSync(()->{try{shown[0]=((List<?>)field(library,ReceiverLibraryActivity.class,"shown")).size();}catch(Exception e){throw new RuntimeException(e);}});if(shown[0]>0)break;}out.putInt("interactive_search_results",shown[0]);require(shown[0]>0,"Early typed query did not publish");
  CountDownLatch images=new CountDownLatch(2);Bitmap[] badges={null,null};test.runOnMainSync(()->LogoRepository.get(c).request("MBC 2",new LogoRepository.Listener(){public void channel(Bitmap b){if(b!=null){badges[0]=b;images.countDown();}}public void provider(String name,Bitmap b){if(b!=null){badges[1]=b;images.countDown();}}}));require(images.await(40,TimeUnit.SECONDS),"Real channel/provider images unavailable");out.putBoolean("real_channel_logo",badges[0]!=null);out.putBoolean("real_provider_logo",badges[1]!=null);boolean[] immediate={false,false};test.runOnMainSync(()->LogoRepository.get(c).request("MBC 2",new LogoRepository.Listener(){public void channel(Bitmap b){immediate[0]=b!=null;}public void provider(String name,Bitmap b){immediate[1]=b!=null;}}));out.putBoolean("channel_and_provider_warm_immediate",immediate[0]&&immediate[1]);require(immediate[0]&&immediate[1],"Warm logo lookup was not immediate");
  Activity apps=test.startActivitySync(new Intent(c,AppsActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));test.runOnMainSync(()->{try{((EditText)field(apps,AppsActivity.class,"query")).setText("YouTube");}catch(Exception e){throw new RuntimeException(e);}});int[] found={0};for(int n=0;n<50;n++){Thread.sleep(100);test.runOnMainSync(()->{try{found[0]=((List<?>)field(apps,AppsActivity.class,"apps")).size();}catch(Exception e){throw new RuntimeException(e);}});if(found[0]>0)break;}out.putBoolean("app_search_works",found[0]>0);require(found[0]>0,"Installed app search failed");
  android.content.SharedPreferences prefs=c.getSharedPreferences("smarthub",0);boolean auto=prefs.getBoolean("osd_receiver_size",true);int percent=prefs.getInt("osd_bar_percent",26);try{for(int size:new int[]{16,26,40}){prefs.edit().putBoolean("osd_receiver_size",false).putInt("osd_bar_percent",size).commit();test.runOnMainSync(()->{try{NowNextView view=new NowNextView(c);SatelliteState s=SatelliteState.read(c);view.bind(s,null,null,null,"");int width=c.getResources().getDisplayMetrics().widthPixels,height=OsdGeometry.window(c);view.measure(View.MeasureSpec.makeMeasureSpec(width,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(height,View.MeasureSpec.EXACTLY));view.layout(0,0,width,height);Rect quality=rect(view,(View)field(view,NowNextView.class,"qualityBar")),detail=rect(view,(View)field(view,NowNextView.class,"signalDetail")),logo=rect(view,(View)field(view,NowNextView.class,"logo")),provider=rect(view,(View)field(view,NowNextView.class,"providerPanel"));require(detail.top>=quality.bottom&&detail.bottom<=height,"Signal detail overflow");require(logo.left<width/4&&provider.right>width*3/4,"Branding positions changed");out.putBoolean("osd_layout_"+size,true);}catch(Exception e){throw new RuntimeException(e);}});}}finally{prefs.edit().putBoolean("osd_receiver_size",auto).putInt("osd_bar_percent",percent).commit();}
  ReceiverCatalog.Channel dubai=db.channel(db.uniqueChannel("DUBAI SPORTS 1 HD"));require(dubai!=null&&dubai.ca==0,"Independent FTA test service missing");prefs.edit().putBoolean("own_dvb_ack",false).commit();Activity watching=test.startActivitySync(new Intent(c,DvbPlaybackActivity.class).putExtra("channel",dubai.id).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));for(int n=0;n<70&&!prefs.getBoolean("own_dvb_ack",false);n++)Thread.sleep(100);out.putBoolean("own_dvb_play_ack",prefs.getBoolean("own_dvb_ack",false));require(out.getBoolean("own_dvb_play_ack"),"Own decoder did not accept FTA playback");require(SatelliteState.read(c).channelId.startsWith("DVB:"),"Own channel identity not published");
  ReceiverPlayback engine=(ReceiverPlayback)field(watching,DvbPlaybackActivity.class,"player");test.runOnMainSync(()->engine.audio(1));int[] audio={0};for(int n=0;n<40;n++){Thread.sleep(100);test.runOnMainSync(()->{try{audio[0]=(Integer)field(watching,DvbPlaybackActivity.class,"audioIndex");}catch(Exception e){throw new RuntimeException(e);}});if(audio[0]==1)break;}out.putBoolean("own_audio_switch_ack",audio[0]==1);require(audio[0]==1,"Audio command not acknowledged");
  String priorIdentity=SatelliteState.read(c).channelId;test.runOnMainSync(()->watching.dispatchKeyEvent(new KeyEvent(KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_CHANNEL_UP)));for(int n=0;n<50&&SatelliteState.read(c).channelId.equals(priorIdentity);n++)Thread.sleep(100);out.putBoolean("own_same_tp_channel_changed",!SatelliteState.read(c).channelId.equals(priorIdentity));require(out.getBoolean("own_same_tp_channel_changed"),"Independent same-TP channel change failed");
  test.runOnMainSync(()->{watching.dispatchKeyEvent(new KeyEvent(KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_MENU));watching.dispatchKeyEvent(new KeyEvent(KeyEvent.ACTION_UP,KeyEvent.KEYCODE_MENU));});test.waitForIdleSync();out.putBoolean("own_player_menu_consumed",true);
 }
}
